// Simula a saída completa do Analista IA + pacote determinístico.
return [{json:{
  pacote_analise:{
    data_referencia:'2026-08-13',
    performance:{investimento_total:150,conversas_iniciadas:15,custo_medio_por_conversa:10,score_tecnico_medio:46,quantidade_registros:3},
    tendencia:{quantidade_objetos:3,fadiga_alta:[{nome:'ANUNCIO_B'}],fadiga_moderada:[],observar:[{nome:'ANUNCIO_C'}],melhora:[{nome:'ANUNCIO_A'}],dados_insuficientes:[]}
  },
  status_analise_ia:'OK',
  parser_usado:'CODE_MANUAL_V3',
  analise_ia:{
    resumo_executivo:'A conta exige atenção principalmente por deterioração do ANUNCIO_B, enquanto ANUNCIO_A apresenta melhora.',
    saude_conta:'atencao',
    confianca_analise:'alta',
    prioridades:[
      {prioridade:1,nivel:'Anúncio',nome:'ANUNCIO_B',diagnostico:'Performance fraca combinada com fadiga alta.',evidencias:['Score técnico 28','Fadiga 90'],acao_recomendada:'REVISAR_CRIATIVO',motivo:'A deterioração recente merece revisão antes de ampliar exposição.',prazo_reavaliacao_dias:3},
      {prioridade:2,nivel:'Anúncio',nome:'ANUNCIO_C',diagnostico:'Resultado fraco com sinal de observação.',evidencias:['Score técnico 20'],acao_recomendada:'OBSERVAR',motivo:'Ainda não há evidência suficiente para ação agressiva.',prazo_reavaliacao_dias:3}
    ],
    oportunidades:[{nome:'ANUNCIO_A',oportunidade:'Candidato a manter e observar para futura escala.',evidencias:['Score técnico 90']}],
    riscos:[],hipoteses_teste:[],nao_fazer:['Não escalar ANUNCIO_B antes de reavaliar o criativo.']
  },
  briefing_gestor:'ANÁLISE IA META ADS\nSaúde da conta: ATENÇÃO\n...'
}}];

// Uma planilha por conta. Permite override pelo workflow chamador.
const entrada=$json||{};
return [{json:{...entrada,CONFIG_PLANILHA:{
  PLANILHA_ID: entrada.planilha_id || '1S2r2y1AiaUnZPUpR0qTp_8Itag5n1DhH6rCrXaFAH1A',
  CONTA: entrada.conta || '742175035567342',
  ABA_ANALISES:'ANALISES IA',
  ABA_PRIORIDADES:'PRIORIDADES IA'
}}}];

// Cria uma linha por execução válida da IA.
if($json.status_analise_ia!=='OK'||!$json.analise_ia){return [];}
const a=$json.analise_ia||{};
const p=$json.pacote_analise||{};
const perf=p.performance||{};
const tend=p.tendencia||{};
const cfg=$json.CONFIG_PLANILHA||{};
const gerado=$now.setZone('America/Sao_Paulo').toISO();
const data=p.data_referencia||$now.setZone('America/Sao_Paulo').minus({days:1}).toFormat('yyyy-MM-dd');
const chave=[cfg.CONTA,data,gerado].join('|');
const prioridades=Array.isArray(a.prioridades)?a.prioridades:[];
const primeira=prioridades[0]||{};
return [{json:{
  PLANILHA_ID:cfg.PLANILHA_ID,
  'CHAVE ANALISE':chave,
  'DATA REFERENCIA':data,
  'GERADO EM':gerado,
  'CONTA':cfg.CONTA,
  'SAUDE CONTA':String(a.saude_conta||'dados_insuficientes').toUpperCase(),
  'CONFIANCA ANALISE':String(a.confianca_analise||'baixa').toUpperCase(),
  'RESUMO EXECUTIVO':String(a.resumo_executivo||''),
  'INVESTIMENTO TOTAL':perf.investimento_total??'',
  'CONVERSAS':perf.conversas_iniciadas??'',
  'CUSTO MEDIO CONVERSA':perf.custo_medio_por_conversa??'',
  'SCORE TECNICO MEDIO':perf.score_tecnico_medio??'',
  'QTD OBJETOS':tend.quantidade_objetos??perf.quantidade_registros??'',
  'FADIGA ALTA':Array.isArray(tend.fadiga_alta)?tend.fadiga_alta.length:0,
  'FADIGA MODERADA':Array.isArray(tend.fadiga_moderada)?tend.fadiga_moderada.length:0,
  'OBSERVAR':Array.isArray(tend.observar)?tend.observar.length:0,
  'MELHORA':Array.isArray(tend.melhora)?tend.melhora.length:0,
  'DADOS INSUFICIENTES':Array.isArray(tend.dados_insuficientes)?tend.dados_insuficientes.length:0,
  'QTD PRIORIDADES':prioridades.length,
  'PRIORIDADE PRINCIPAL':String(primeira.nome||''),
  'ACAO PRINCIPAL':String(primeira.acao_recomendada||''),
  'BRIEFING GESTOR':String($json.briefing_gestor||''),
  'PARSER':String($json.parser_usado||'')
}}];

// Expande as prioridades em linhas independentes para dashboard e acompanhamento.
if($json.status_analise_ia!=='OK'||!$json.analise_ia){return [];}
const a=$json.analise_ia||{};const p=$json.pacote_analise||{};const cfg=$json.CONFIG_PLANILHA||{};
const gerado=$now.setZone('America/Sao_Paulo').toISO();
const data=p.data_referencia||$now.setZone('America/Sao_Paulo').minus({days:1}).toFormat('yyyy-MM-dd');
const chaveAnalise=[cfg.CONTA,data,gerado].join('|');
const prioridades=Array.isArray(a.prioridades)?a.prioridades:[];
return prioridades.map((x,i)=>({json:{
  PLANILHA_ID:cfg.PLANILHA_ID,
  'CHAVE PRIORIDADE':[chaveAnalise,x.prioridade||i+1].join('|'),
  'CHAVE ANALISE':chaveAnalise,
  'DATA REFERENCIA':data,
  'CONTA':cfg.CONTA,
  'ORDEM':Number(x.prioridade||i+1),
  'NIVEL':String(x.nivel||''),
  'NOME OBJETO':String(x.nome||''),
  'ACAO RECOMENDADA':String(x.acao_recomendada||'OBSERVAR'),
  'DIAGNOSTICO':String(x.diagnostico||''),
  'MOTIVO':String(x.motivo||''),
  'EVIDENCIAS':Array.isArray(x.evidencias)?x.evidencias.join(' | '):'',
  'REAVALIAR EM DIAS':Number(x.prazo_reavaliacao_dias||3),
  'STATUS GESTOR':'PENDENTE',
  'OBSERVACAO GESTOR':'',
  'ATUALIZADO EM':gerado
}}));

